// One row per Google attribute: where its value comes from in Shopify, where it goes, and the rule it has to pass.
const rows = [
  { sort_order: 10, field: 'title', kind: 'shopify_native', target: '', source: 'product.title', required: true, rule: 'max_len:150' },
  { sort_order: 20, field: 'description', kind: 'shopify_native', target: '', source: 'product.description', required: true, rule: 'min_len:1' },
  { sort_order: 30, field: 'image_link', kind: 'shopify_native', target: '', source: 'product.featured_image', required: true, rule: 'min_image_px:500' },
  { sort_order: 40, field: 'brand', kind: 'shopify_native', target: '', source: 'product.vendor', required: true, rule: 'not:Unbranded' },
  { sort_order: 45, field: 'google_product_category', kind: 'shopify_native', target: '', source: 'product.category', required: true, rule: '' },
  { sort_order: 50, field: 'gtin', kind: 'shopify_native', target: '', source: 'variant.barcode', required: true, rule: 'gtin;alt:mpn+brand' },
  { sort_order: 60, field: 'mpn', kind: 'app_metafield', target: 'variant:mm-google-shopping.mpn', source: 'variant.sku', required: false, rule: '' },
  { sort_order: 70, field: 'condition', kind: 'app_metafield', target: 'variant:mm-google-shopping.condition', source: 'static', static_value: 'new', required: true, rule: '' },
  { sort_order: 80, field: 'product_highlight', kind: 'supplemental', target: 'productHighlights', source: 'product.highlights', required: false, rule: 'min_items:2;max_items:10;max_len:150' },
  { sort_order: 90, field: 'product_detail', kind: 'supplemental', target: 'productDetails', source: 'product.detail_fields', required: false, rule: 'max_items:100;max_len:150' },
  { sort_order: 100, field: 'material', kind: 'supplemental', target: 'material', source: 'product.category_metafield:material', required: false, rule: '' }
];
return rows.map(r => ({ json: { channel: 'google', static_value: '', active: true, ...r } }));

// Finds the primary source the Google & YouTube app feeds, and any supplemental source this template made before.
const s = $('Setup settings').first().json;
const sources = $json.dataSources || [];
const primaries = sources.filter(d => d.primaryProductDataSource);
const primary = s.primary_data_source
  ? primaries.find(d => String(d.dataSourceId) === String(s.primary_data_source))
  : (primaries.length === 1 ? primaries[0] : null);
if (!primary) throw new Error('Set primary_data_source in Setup settings. Primary sources found: ' +
  (primaries.map(d => `${d.displayName} (${d.dataSourceId})`).join(', ') || 'none'));
const existing = sources.find(d => d.supplementalProductDataSource && d.displayName === s.supplemental_name);
return [{ json: { primary, existing_supplemental: existing ? existing.name : '' } }];

// Updating the default rule replaces the whole rule, so keep every source already in it and add ours once.
const plan = $('Plan the link').first().json;
const supplemental = plan.existing_supplemental || $('Create the supplemental source').first().json.name;
const current = plan.primary.primaryProductDataSource.defaultRule?.takeFromDataSources || [{ self: true }];
const linked = current.some(r => r.supplementalDataSourceName === supplemental);
const rule = linked ? current : current.concat([{ supplementalDataSourceName: supplemental }]);
return [{ json: { primary: plan.primary.name, supplemental, linked,
  body: { primaryProductDataSource: { defaultRule: { takeFromDataSources: rule } } } } }];

// Builds the product query from the field map and the detail fields, so a new field is a new row, not a new query.
const s = $('Check settings').first().json;
const fm = $('Get field map').all().map(i => i.json);
// Publication.name is deprecated: a sales channel's publication is found through the app behind its catalog.
const pubs = ($('Find the Google channel').first().json.data || {}).publications?.nodes || [];
const appOf = p => (((p.catalog || {}).apps || {}).nodes || [])[0] || {};
const pub = pubs.find(p => appOf(p).title === s.sales_channel || appOf(p).handle === s.sales_channel);
if (!pub) throw new Error('No sales channel called "' + s.sales_channel + '". Install the Google & YouTube app, or fix sales_channel. Channels found: ' +
  pubs.map(p => appOf(p).title).filter(Boolean).join(', '));
const split = ref => { const dot = ref.lastIndexOf('.'); return [ref.slice(0, dot), ref.slice(dot + 1)]; };
const appFields = owner => fm.filter(r => r.kind === 'app_metafield' && r.target.startsWith(owner + ':')).map(r => {
  const [ns, key] = split(r.target.split(':')[1]);
  return `g_${r.field}: metafield(namespace: "${ns}", key: "${key}") { value }`;
}).join('\n          ');
const details = (s.detail_fields || []).map((d, i) => {
  const [ns, key] = split(d.metafield);
  return `d${i}: metafield(namespace: "${ns}", key: "${key}") { value reference { ... on Metaobject { displayName } } references(first: 5) { nodes { ... on Metaobject { displayName } } } }`;
}).join('\n      ');
const [hns, hkey] = split(s.highlights_metafield);
const query = `query GoogleSource($q: String!, $pub: ID!, $after: String) {
  products(first: ${s.page_size}, after: $after, query: $q) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id legacyResourceId title handle status vendor descriptionHtml tags
      category { id fullName }
      publishedOnPublication(publicationId: $pub)
      featuredMedia { ... on MediaImage { image { url width height } } }
      highlights: metafield(namespace: "${hns}", key: "${hkey}") { type value }
      material: metafield(namespace: "shopify", key: "material") { references(first: 3) { nodes { ... on Metaobject { label: field(key: "label") { value } } } } }
      ${details}
      ${appFields('product')}
      variants(first: 1) {
        nodes {
          id legacyResourceId sku price barcodes(first: 5) { nodes { type value } }
          ${appFields('variant')}
        }
      }
    }
  }
}`;
const q = s.product_ids.length ? s.product_ids.map(id => 'id:' + id).join(' OR ') : s.product_query;
return [{ json: { query, variables: { q, pub: pub.id, after: null } } }];

// Per product, per row in the field map: the Shopify source against what Google gets now, and what to do about it.
// Source full, Google empty: fill. Different: update (Shopify wins). Same: none.
// Source empty, Google full: leave (a fix made by hand is never wiped). Both empty: flag (the pre-check decides if it matters).
const s = $('Check settings').first().json;
const fm = $('Get field map').all().map(i => i.json).sort((a, b) => a.sort_order - b.sort_order);
const last = Object.fromEntries($('Get last state').all().filter(i => i.json.product_id).map(i => [String(i.json.product_id), i.json]));
const pubId = $('Build the query').first().json.variables.pub;
const parse = (t, d) => { try { return JSON.parse(t || ''); } catch (e) { return d; } };

const text = html => String(html || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const labels = mf => ((mf && mf.references && mf.references.nodes) || []).map(n => n && n.label && n.label.value).filter(Boolean);
// Highlights from a list metafield, a multi-line text field, or the bullets of a rich text field
const bullets = mf => {
  if (!mf || !mf.value) return [];
  if (mf.type === 'multi_line_text_field') return mf.value.split(/\n+/).map(t => t.replace(/^[-•*]\s*/, '').trim()).filter(Boolean);
  const v = parse(mf.value, null);
  if (Array.isArray(v)) return v.map(t => String(t).trim()).filter(Boolean);
  const out = [];
  const flat = n => n.value || (n.children || []).map(flat).join('');
  const walk = n => { if (!n) return; if (n.type === 'list-item') { const t = flat(n).replace(/\s+/g, ' ').trim(); if (t) out.push(t); return; } (n.children || []).forEach(walk); };
  walk(v);
  return out;
};
// One product detail per entry in detail_fields: a metaobject's name, a list joined with commas, or the value with its unit
const withUnit = (v, unit) => !unit ? v : v + (/^[°%]/.test(unit) ? '' : ' ') + unit;
const details = p => (s.detail_fields || []).map((d, i) => {
  const mf = p['d' + i];
  if (!mf) return null;
  const refs = ((mf.references && mf.references.nodes) || []).map(n => n && n.displayName).filter(Boolean);
  let value = refs.length ? refs.join(', ') : (mf.reference && mf.reference.displayName) || '';
  if (!value && mf.value) {
    const j = parse(mf.value, null);
    if (Array.isArray(j)) value = j.join(', ');
    else if (j && typeof j === 'object' && 'value' in j) value = withUnit(String(j.value), j.unit ? '' : d.unit);
    else if (/^-?\d+(\.\d+)?$/.test(mf.value)) value = withUnit(String(Number(mf.value)), d.unit);   // 4.0 reads as 4
    else value = withUnit(String(mf.value), d.unit);
  }
  return value ? { section: d.section || 'Specifications', name: d.name, value } : null;
}).filter(Boolean);

const isEmpty = v => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
// Shopify 2026-10 keeps barcodes as a typed list: the GTIN is the GTIN, UPC, EAN or ISBN entry, or an untyped one
const gtinOf = v => { const ns = (v.barcodes && v.barcodes.nodes) || []; const b = ns.find(n => ['GTIN', 'UPC', 'EAN', 'ISBN'].includes(n.type)) || ns.find(n => !n.type); return b ? b.value : ''; };
const same = (a, b) => JSON.stringify(a ?? '') === JSON.stringify(b ?? '');
const rules = row => (row.rule || '').split(';').map(t => t.trim()).filter(Boolean).map(t => { const i = t.indexOf(':'); return i < 0 ? [t, ''] : [t.slice(0, i), t.slice(i + 1)]; });
const rule = (row, name) => (rules(row).find(r => r[0] === name) || [])[1];

function resolveSource(row, p, v) {
  switch (row.source) {
    case 'product.title': return p.title || '';
    case 'product.description': return text(p.descriptionHtml);
    case 'product.featured_image': { const im = p.featuredMedia && p.featuredMedia.image; return im && im.url ? { url: im.url, width: im.width || 0, height: im.height || 0 } : null; }
    case 'product.vendor': return String(p.vendor || '').trim();
    case 'product.category': return p.category && !/\/na$/.test(p.category.id) ? p.category.fullName : '';   // "Uncategorized" counts as none
    case 'variant.barcode': return String(gtinOf(v)).replace(/\s+/g, '');
    case 'variant.sku': return String(v.sku || '').trim();
    case 'static': return row.static_value || '';
    case 'product.highlights': return bullets(p.highlights);
    case 'product.detail_fields': return details(p);
    case 'product.category_metafield:material': return labels(p.material).join('/');
    default: return null;
  }
}

// Supplemental values are shaped to Google's limits here, so the compare sees exactly what would be sent.
function shape(row, val) {
  const max = Number(rule(row, 'max_len')) || 150, n = Number(rule(row, 'max_items')) || 100, min = Number(rule(row, 'min_items')) || 0;
  if (row.field === 'product_highlight') {
    const list = (val || []).filter(t => t.length <= max).slice(0, n);
    return list.length >= min ? list : [];   // Google wants at least 2 highlights, so a single one is sent as none
  }
  if (row.field === 'product_detail') {
    return (val || []).filter(d => d.value.length <= max).slice(0, n)
      .map(d => ({ sectionName: d.section, attributeName: d.name, attributeValue: d.value }));
  }
  return val;
}

function googleNow(row, p, v, prev, src) {
  if (row.kind === 'shopify_native') return src;                       // the app reads these straight from Shopify
  if (row.kind === 'app_metafield') {
    const mf = (row.target.startsWith('variant:') ? v : p)['g_' + row.field];
    return mf && mf.value != null ? mf.value : '';
  }
  return parse(prev.sent, {})[row.target] ?? '';                       // supplemental: what Merchant Center last accepted
}

const out = [];
for (const page of $input.all()) {
  if (page.json.errors || !page.json.data) throw new Error('Shopify read failed, so nothing changed: ' + JSON.stringify(page.json.errors || page.json).slice(0, 400));
  for (const p of page.json.data.products.nodes) {
    const id = String(p.legacyResourceId);
    const prev = last[id] || {};
    const v = (p.variants.nodes || [])[0] || {};
    const fields = [], metafields = [], supplemental = {};
    let supplementalChanged = false;
    for (const row of fm) {
      let src = resolveSource(row, p, v);
      if (row.kind === 'supplemental') src = shape(row, src);
      const now = googleNow(row, p, v, prev, src);
      let action;
      if (row.kind === 'shopify_native') action = isEmpty(src) ? 'flag' : 'none';
      else if (!isEmpty(src) && isEmpty(now)) action = 'fill';
      else if (!isEmpty(src) && !same(src, now)) action = 'update';
      else if (!isEmpty(src)) action = 'none';
      else if (!isEmpty(now)) action = 'leave';
      else action = 'flag';
      const value = ['fill', 'update', 'none'].includes(action) ? src : now;
      fields.push({ field: row.field, kind: row.kind, source: row.source, action, value, required: row.required, rule: row.rule || '' });
      if (row.kind === 'app_metafield' && (action === 'fill' || action === 'update')) {
        const [owner, ref] = row.target.split(':');
        const dot = ref.lastIndexOf('.');
        metafields.push({ ownerId: owner === 'variant' ? v.id : p.id, namespace: ref.slice(0, dot), key: ref.slice(dot + 1), type: 'single_line_text_field', value: String(src) });
      }
      if (row.kind === 'supplemental') {
        if (!isEmpty(value)) supplemental[row.target] = value;
        if (action === 'fill' || action === 'update') supplementalChanged = true;
      }
    }
    out.push({ json: {
      product_id: id, product_gid: p.id, variant_id: String(v.legacyResourceId || ''), title: p.title || '', status: p.status,
      excluded: !!s.exclude_tag && (p.tags || []).some(t => t.toLowerCase() === s.exclude_tag.toLowerCase()),
      published: p.publishedOnPublication === true, image: (p.featuredMedia && p.featuredMedia.image && p.featuredMedia.image.url) || '',
      vendor: p.vendor || '', sku: v.sku || '', barcode: gtinOf(v), price: Number(v.price || 0), publication_id: pubId,
      fields, metafields, supplemental, supplemental_changed: supplementalChanged,
      last_state: prev.state || null, last_missing: parse(prev.missing, []), slack_channel: prev.slack_channel || '', slack_ts: prev.slack_ts || ''
    } });
  }
}
return out;

// Every required field present and every rule met: the product goes on the Google channel. Otherwise it comes off and is held.
const s = $('Check settings').first().json;
const LABELS = { title: 'Title', description: 'Description', image_link: 'Main image', brand: 'Brand', google_product_category: 'Shopify category', gtin: 'GTIN (barcode)', mpn: 'MPN', condition: 'Condition' };
// What to do about a missing field that can't be fixed from Slack
const MISSING_HINT = { google_product_category: 'Pick a category in Shopify admin: the Google & YouTube app turns it into Google\'s product category.' };
// The Shopify field a reviewer can fix from Slack for each source (images are fixed in Shopify admin)
const EDIT = { 'variant.barcode': 'barcode', 'variant.sku': 'sku', 'product.vendor': 'vendor', 'product.title': 'title' };
const isEmpty = v => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
const rules = r => (r.rule || '').split(';').map(t => t.trim()).filter(Boolean).map(t => { const i = t.indexOf(':'); return i < 0 ? [t, ''] : [t.slice(0, i), t.slice(i + 1)]; });
// GTIN-8, 12, 13 or 14 with a valid GS1 check digit
const validGtin = g => {
  if (!/^(\d{8}|\d{12}|\d{13}|\d{14})$/.test(g)) return false;
  const d = g.padStart(14, '0').split('').map(Number);
  const sum = d.slice(0, 13).reduce((a, n, i) => a + n * (i % 2 === 0 ? 3 : 1), 0);
  return (10 - (sum % 10)) % 10 === d[13];
};
const gtinHint = g => {
  if (/^\d{11}$/.test(g) && validGtin('0' + g)) return 'Looks like a UPC missing its leading zero: 0' + g;
  if (!/^\d+$/.test(g)) return 'Letters or symbols in it: probably a supplier code, not a barcode. Clear it if the product has no GTIN.';
  return '';
};

const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const byField = Object.fromEntries(p.fields.map(f => [f.field, f]));
  const problems = {};
  // pass 1: each field's own rules
  for (const f of p.fields) {
    if (f.kind === 'supplemental') continue;
    const v = f.value;
    if (isEmpty(v)) { if (f.required) problems[f.field] = { problem: 'missing', suggestion: MISSING_HINT[f.field] || '' }; continue; }
    for (const [name, arg] of rules(f)) {
      const t = typeof v === 'string' ? v : '';
      if (name === 'max_len' && t.length > Number(arg)) problems[f.field] = { problem: `over ${arg} characters (${t.length})` };
      if (name === 'min_len' && t.length < Number(arg)) problems[f.field] = { problem: 'missing' };
      if (name === 'min_image_px' && (Number(v.width) < Number(arg) || Number(v.height) < Number(arg))) problems[f.field] = { problem: `smaller than ${arg} x ${arg} px (${v.width} x ${v.height})` };
      if (name === 'not' && t.toLowerCase() === arg.toLowerCase()) problems[f.field] = { problem: `"${t}" is not a brand` };
      if (name === 'gtin' && !validGtin(t)) problems[f.field] = { problem: `${t} is not a valid GTIN`, suggestion: gtinHint(t) };
    }
  }
  // pass 2: an empty GTIN is fine when every alt: field is present and clean (MPN + brand).
  // A GTIN that's there but wrong stays a problem: a wrong barcode is worse than none.
  for (const f of p.fields) {
    const alt = (rules(f).find(r => r[0] === 'alt') || [])[1];
    if (!alt || !isEmpty(f.value) || !problems[f.field]) continue;
    const need = alt.split('+');
    if (need.every(k => byField[k] && !isEmpty(byField[k].value) && !problems[k])) delete problems[f.field];
    else {
      const lacking = need.filter(k => !byField[k] || isEmpty(byField[k].value) || problems[k]);
      problems[f.field] = { problem: 'no GTIN, and no ' + lacking.map(k => (LABELS[k] || k).split(' ')[0]).join(' or ') + ' to fall back on',
        edit_also: lacking.map(k => byField[k] && EDIT[byField[k].source]).filter(Boolean) };
    }
  }
  const missing = Object.entries(problems).map(([field, x]) => {
    const f = byField[field];
    const edit = [EDIT[f.source]].concat(x.edit_also || []).filter(Boolean);
    return { field, label: LABELS[field] || field, problem: x.problem, suggestion: x.suggestion || '', edit: [...new Set(edit)] };
  });
  // A product tagged with exclude_tag stays off the channel with no card, whatever its fields look like
  const state = p.status !== 'ACTIVE' ? 'off' : p.excluded ? 'excluded' : (missing.length ? 'held' : 'live');
  if (state === 'excluded') missing.length = 0;
  const publish = state === 'live' && !p.published;
  const unpublish = (state === 'held' || state === 'excluded') && p.published;
  const key = list => JSON.stringify(list.map(m => m.field + ':' + m.problem).sort());
  const missingChanged = key(missing) !== key(p.last_missing || []);
  let card = null;
  if (state === 'held' && (!p.slack_ts || missingChanged || s.product_ids.length)) card = p.slack_ts ? 'update' : 'post';
  if (state === 'live' && p.slack_ts && (['held', 'excluded'].includes(p.last_state) || s.product_ids.length)) card = 'resolve';
  if (state === 'excluded' && p.slack_ts && (p.last_state === 'held' || s.product_ids.length)) card = 'excluded';
  out.push({ json: { ...p, state, missing, publish, unpublish, card } });
}
return out;

// One Shopify request per 10 products that need a change: the app's fields (metafieldsSet) plus the channel switch
// (publishablePublish or publishableUnpublish). Always returns at least one item so the run carries on.
const todo = $input.all().map(i => i.json).filter(p => p.metafields.length || p.publish || p.unpublish);
const batches = [];
for (let i = 0; i < todo.length; i += 10) batches.push(todo.slice(i, i + 10));
const out = batches.map(batch => {
  const decl = [], body = [], variables = {};
  if (batch.some(p => p.publish || p.unpublish)) { decl.push('$pub: [PublicationInput!]!'); variables.pub = [{ publicationId: batch[0].publication_id }]; }
  batch.forEach((p, n) => {
    if (p.metafields.length) { decl.push(`$mf${n}: [MetafieldsSetInput!]!`); variables['mf' + n] = p.metafields; body.push(`p${n}_fields: metafieldsSet(metafields: $mf${n}) { userErrors { field message } }`); }
    if (p.publish || p.unpublish) { decl.push(`$id${n}: ID!`); variables['id' + n] = p.product_gid; }
    if (p.publish) body.push(`p${n}_on: publishablePublish(id: $id${n}, input: $pub) { userErrors { field message } }`);
    if (p.unpublish) body.push(`p${n}_off: publishableUnpublish(id: $id${n}, input: $pub) { userErrors { field message } }`);
  });
  return { json: { product_ids: batch.map(p => p.product_id), query: `mutation GoogleChannel(${decl.join(', ')}) {\n  ${body.join('\n  ')}\n}`, variables } };
});
return out.length ? out : [{ json: { product_ids: [], query: '', variables: {} } }];

// One feed_status row per product. A product whose Shopify write failed keeps its old state, so tomorrow's run tries again.
// In a dry run nothing is saved and nothing goes further: read the Pre-check output instead.
const s = $('Check settings').first().json;
if (s.dry_run) return [];
const plans = $('Plan the writes').all();
const writes = $('Write to Shopify').isExecuted ? $('Write to Shopify').all() : [];
const failed = new Set();
plans.forEach((pl, i) => {
  const w = (writes[i] || {}).json;
  if (!w) return;
  pl.json.product_ids.forEach((id, n) => {
    const errs = (w.errors || []).length || !w.data ? ['request failed']
      : ['fields', 'on', 'off'].flatMap(k => (w.data[`p${n}_${k}`] && w.data[`p${n}_${k}`].userErrors) || []);
    if (errs.length) failed.add(id);
  });
});
return $('Pre-check').all().map(i => i.json).filter(p => !failed.has(p.product_id)).map(p => ({ json: {
  product_id: p.product_id, state: p.state, missing: JSON.stringify(p.missing),
  app_fields: JSON.stringify(Object.fromEntries(p.fields.filter(f => f.kind === 'app_metafield').map(f => [f.field, f.value]))),
  checked_at: new Date().toISOString()
} }));

// One supplemental row per live product whose highlights, details or material changed since Merchant Center last accepted them.
// An insert replaces that offer's whole row in the supplemental source, so every value goes each time.
const s = $('Check settings').first().json;
if (!s.supplemental_enabled || s.dry_run || !s.supplemental_data_source) return [];
const out = [];
for (const p of $('Pre-check').all().map(i => i.json)) {
  if (p.state !== 'live' || !p.supplemental_changed || !p.variant_id) continue;
  if (!Object.keys(p.supplemental).length) continue;
  const offerId = s.offer_id_template.replace('{product_id}', p.product_id).replace('{variant_id}', p.variant_id);
  out.push({ json: { product_id: p.product_id, sent: JSON.stringify(p.supplemental),
    body: { offerId, contentLanguage: s.content_language, feedLabel: s.feed_label, productAttributes: p.supplemental } } });
}
return out;

// One review card per held product, updated in place. A product that passes later gets its card marked fixed.
const s = $('Check settings').first().json;
if (!s.review_channel) return [];
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = DateTime.now().setZone(s.timezone).toFormat('h:mm a, d LLL');
const saved = new Set($('Status rows').all().map(i => i.json.product_id));
const out = [];
for (const p of $('Pre-check').all().map(i => i.json)) {
  if (!p.card || !saved.has(p.product_id)) continue;
  const admin = 'https://admin.shopify.com/store/' + s.admin_handle + '/products/' + p.product_id;
  const thumb = sec => { if (/^https:\/\//.test(p.image)) sec.accessory = { type: 'image', image_url: p.image, alt_text: String(p.title).slice(0, 100) }; return sec; };
  const blocks = [];
  if (p.card === 'excluded') {
    blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Excluded from Google' } });
    blocks.push(thumb({ type: 'section', text: { type: 'mrkdwn', text: '*' + esc(p.title) + '*\nTagged `' + esc(s.exclude_tag) + '`, so it stays off the Google & YouTube channel and is no longer checked. Remove the tag to bring it back.' } }));
    blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Shopify admin' }, url: admin, action_id: 'link_admin' } ] });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Excluded at ' + when } ] });
  } else if (p.card === 'resolve') {
    blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Fixed: on Google' } });
    blocks.push(thumb({ type: 'section', text: { type: 'mrkdwn', text: '*' + esc(p.title) + '*\nEvery field Google needs is there now, so it is back on the Google & YouTube channel. The read-back reports anything Google still rejects.' } }));
    blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Shopify admin' }, url: admin, action_id: 'link_admin' } ] });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: ':white_check_mark: Passed the pre-check at ' + when } ] });
  } else {
    blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Held from Google' } });
    const lines = p.missing.map(m => '• *' + esc(m.label) + '*: ' + esc(m.problem) + (m.suggestion ? '\n      _' + esc(m.suggestion) + '_' : ''));
    blocks.push(thumb({ type: 'section', text: { type: 'mrkdwn', text: ('*' + esc(p.title) + '*\n' + lines.join('\n')).slice(0, 2900) } }));
    blocks.push({ type: 'section', fields: [
      { type: 'mrkdwn', text: '*Brand*\n' + esc(p.vendor || 'none') },
      { type: 'mrkdwn', text: '*SKU*\n' + esc(p.sku || 'none') },
      { type: 'mrkdwn', text: '*Barcode*\n' + esc(p.barcode || 'none') },
      { type: 'mrkdwn', text: '*Price*\n' + (p.price > 0 ? s.currency + ' ' + p.price.toFixed(2) : 'n/a') }
    ] });
    const buttons = [];
    if (p.missing.some(m => m.edit.length)) buttons.push({ type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Edit' }, action_id: 'google_edit', value: p.product_id });
    buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Recheck' }, action_id: 'google_recheck', value: p.product_id });
    buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Shopify admin' }, url: admin, action_id: 'link_admin' });
    blocks.push({ type: 'actions', elements: buttons });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Off the Google & YouTube channel until fixed. Edit saves to the Shopify product, then rechecks. Checked ' + when } ] });
  }
  out.push({ json: { product_id: p.product_id, channel: p.slack_channel || s.review_channel, ts: p.slack_ts || '',
    text: ({ resolve: 'Fixed: on Google: ', excluded: 'Excluded from Google: ' }[p.card] || 'Held from Google: ') + p.title, blocks } });
}
return out;

// The daily counts for the log channel. A one-product recheck from Slack doesn't post a summary.
const s = $('Check settings').first().json;
if (s.product_ids.length || !s.log_channel) return [];
const ps = $('Pre-check').all().map(i => i.json);
const writes = $('Write to Shopify').isExecuted ? $('Write to Shopify').all().map(i => i.json) : [];
const failed = writes.filter(w => (w.errors || []).length || !w.data).length;
const live = ps.filter(p => p.state === 'live'), held = ps.filter(p => p.state === 'held'), off = ps.filter(p => p.state === 'off');
const excluded = ps.filter(p => p.state === 'excluded');
const reasons = {};
held.forEach(p => p.missing.forEach(m => {
  const k = m.label + ': ' + m.problem.replace(/^.*? is not a valid GTIN$/, 'not a valid GTIN').replace(/\(\d+.*\)$/, '').trim();
  reasons[k] = (reasons[k] || 0) + 1;
}));
const top = Object.entries(reasons).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, n]) => `    ${n} × ${k}`);
const count = action => ps.reduce((a, p) => a + p.fields.filter(f => f.kind === 'app_metafield' && f.action === action).length, 0);
const on = ps.filter(p => p.publish).length, offGoogle = held.filter(p => p.unpublish).length, exclOff = excluded.filter(p => p.unpublish).length;
const lines = [
  `Checked ${ps.length} product${ps.length === 1 ? '' : 's'} for Google.`,
  `• ${live.length} pass` + (on ? `, ${on} went on Google` : ''),
  `• ${held.length} held` + (offGoogle ? `, ${offGoogle} came off Google` : '') + (top.length ? ':\n' + top.join('\n') : ''),
  `• ${count('fill')} Google fields filled, ${count('update')} updated`
];
if (excluded.length) lines.push(`• ${excluded.length} excluded by the ${s.exclude_tag} tag` + (exclOff ? `, ${exclOff} came off Google` : ''));
if (off.length) lines.push(`• ${off.length} not active, left alone`);
if (failed) lines.push(`• ${failed} Shopify write${failed === 1 ? '' : 's'} failed; those products keep their old state`);
return [{ json: { channel: s.log_channel, text: lines.join('\n') } }];

// Reads a Slack button click or a submitted Edit modal, and builds the string Slack signs.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const sig = { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] };
if (b.type === 'view_submission') {
  const m = JSON.parse(b.view.private_metadata);
  const values = {};
  for (const block of Object.values(b.view.state.values)) for (const [key, el] of Object.entries(block)) values[key] = String(el.value || '').trim();
  return [{ json: { ...sig, action: 'edit_submit', product_id: m.product_id, channel: m.channel, ts: m.ts, values, user: b.user.username } }];
}
const a = b.actions[0];
return [{ json: { ...sig, action: a.action_id.replace('google_', ''), product_id: a.value,
  trigger_id: b.trigger_id, user: b.user.username, channel: b.channel.id, ts: b.message.ts } }];

