// The Edit modal shows only the Shopify fields behind what was flagged, filled with today's values (or the suggested GTIN fix).
const c = $('Read the click').first().json;
const st = $('Get status').first().json || {};
const p = ($('Read the product').first().json.data || {}).product || {};
const v = ((p.variants || {}).nodes || [])[0] || {};
const GTIN_TYPES = ['GTIN', 'UPC', 'EAN', 'ISBN'];
const gtin = ((v.barcodes || {}).nodes || []).find(n => GTIN_TYPES.includes(n.type) || !n.type);
const parse = (t, d) => { try { return JSON.parse(t || ''); } catch (e) { return d; } };
const missing = parse(st.missing, []);
const want = new Set(missing.flatMap(m => m.edit || []));
// issues Merchant Center reported in the read-back open the same Shopify fields
const ATTR = { gtin: ['barcode'], mpn: ['sku'], brand: ['vendor'], title: ['title'] };
const googleIssues = parse(st.google_issues, []).filter(x => x.severity === 'DISAPPROVED' || x.severity === 'DEMOTED');
googleIssues.forEach(x => (ATTR[x.attribute] || []).forEach(k => want.add(k)));
const hint = Object.fromEntries(missing.map(m => [m.field, m]));
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const input = (key, label, initial, opts = {}) => {
  const el = { type: 'plain_text_input', action_id: key, ...(opts.el || {}) };
  if (initial) el.initial_value = String(initial).slice(0, opts.max || 3000);
  const b = { type: 'input', block_id: 'field_' + key, label: { type: 'plain_text', text: label }, element: el, optional: !!opts.optional };
  if (opts.hint) b.hint = { type: 'plain_text', text: opts.hint.slice(0, 150) };
  return b;
};
const summary = missing.map(m => '• ' + esc(m.label) + ': ' + esc(m.problem))
  .concat(googleIssues.map(x => '• Google: ' + esc(x.description) + (x.attribute ? ' (' + esc(x.attribute) + ')' : '')));
const blocks = [ { type: 'section', text: { type: 'mrkdwn', text: '*' + esc(p.title || 'Product') + '*\n' + (summary.join('\n') || 'Nothing flagged right now.') } } ];
const gtinSuggest = ((hint.gtin && hint.gtin.suggestion) || '').match(/:\s*(\d{12,14})$/);
if (want.has('barcode')) blocks.push(input('barcode', 'GTIN (barcode)', gtinSuggest ? gtinSuggest[1] : (gtin ? gtin.value : ''), { optional: true, max: 14, el: { max_length: 14 },
  hint: gtinSuggest ? 'Filled with the suggested fix. Leave blank if the product has no barcode.' : '8, 12, 13 or 14 digits from the box. Leave blank if the product has none.' }));
if (want.has('sku')) blocks.push(input('sku', 'MPN (manufacturer part number)', v.sku, { el: { max_length: 70 }, hint: 'Saved as the variant SKU, which feeds Google the MPN.' }));
if (want.has('vendor')) blocks.push(input('vendor', 'Brand', p.vendor === 'Unbranded' ? '' : p.vendor, { el: { max_length: 70 } }));
if (want.has('title')) blocks.push(input('title', 'Title', p.title, { max: 150, el: { max_length: 150 }, hint: 'Google allows 150 characters.' }));
if (blocks.length === 1) blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Nothing here can be fixed from Slack (an image, say). Fix it in Shopify admin, then tap Recheck.' } ] });
else blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Saving writes these to the Shopify product, then rechecks it for Google.' } ] });
const view = { type: 'modal', callback_id: 'google_edit_submit', private_metadata: JSON.stringify({ product_id: c.product_id, channel: c.channel, ts: c.ts }),
  title: { type: 'plain_text', text: 'Fix for Google' }, close: { type: 'plain_text', text: 'Cancel' }, blocks };
if (blocks.length > 2) view.submit = { type: 'plain_text', text: 'Save and recheck' };
return [{ json: { view_id: ($('Open loading modal').first().json.view || {}).id, view } }];

// Turns the modal into one Shopify request on the source fields: brand and title on the product, barcode and SKU on the variant.
// Google's own fields are never typed in here; the recheck derives them from these.
const c = $('Read the click').first().json;
const got = c.values || {};
const p = ($('Read the product').first().json.data || {}).product || {};
const v = ((p.variants || {}).nodes || [])[0] || {};
const has = k => Object.prototype.hasOwnProperty.call(got, k);
const product = { id: p.id }, variant = { id: v.id };
let doProduct = false, doVariant = false;
if (has('vendor') && got.vendor && got.vendor !== p.vendor) { product.vendor = got.vendor; doProduct = true; }
if (has('title') && got.title && got.title !== p.title) { product.title = got.title.replace(/\s+/g, ' '); doProduct = true; }
// Barcodes are a typed list that a write replaces whole: swap the GTIN entry and keep any others (an ASIN, say).
// Saving it as type GTIN makes Shopify check the digits too.
const GTIN_TYPES = ['GTIN', 'UPC', 'EAN', 'ISBN'];
const barcodes = ((v.barcodes || {}).nodes || []);
const isGtin = n => GTIN_TYPES.includes(n.type) || !n.type;
const oldGtin = (barcodes.find(isGtin) || {}).value || '';
const newGtin = has('barcode') ? got.barcode.replace(/\s+/g, '') : oldGtin;
if (newGtin !== oldGtin) {
  variant.barcodes = barcodes.filter(n => !isGtin(n)).map(n => ({ type: n.type, value: n.value }))
    .concat(newGtin ? [{ type: 'GTIN', value: newGtin }] : []);
  doVariant = true;
}
if (has('sku') && got.sku && got.sku !== v.sku) { variant.inventoryItem = { sku: got.sku }; doVariant = true; }
const query = `mutation GoogleSourceEdit($product: ProductUpdateInput!, $pid: ID!, $variants: [ProductVariantsBulkInput!]!, $doProduct: Boolean!, $doVariant: Boolean!) {
  productUpdate(product: $product) @include(if: $doProduct) { product { id } userErrors { field message } }
  productVariantsBulkUpdate(productId: $pid, variants: $variants) @include(if: $doVariant) { productVariants { id sku barcodes(first: 5) { nodes { type value } } } userErrors { field message } }
}`;
return [{ json: { changed: doProduct || doVariant, query, variables: { product, pid: p.id, variants: [variant], doProduct, doVariant } } }];

