// One item per Shopify product from Merchant Center's processed products: approved, limited, disapproved or pending in the
// configured country, with the item-level issues that apply there. The Google & YouTube app's offer id carries the Shopify ids.
const cfg = $('Read-back settings').first().json;
const products = $input.all().flatMap(i => i.json.products || []);
const country = cfg.country;
const byProduct = {};
let unmatched = 0;
for (const g of products) {
  const m = String(g.offerId || '').match(new RegExp(cfg.offer_id_pattern));
  if (!m) { unmatched++; continue; }
  const pid = m[1];
  const st = g.productStatus || {};
  // only Shopping ads and free listings; Display, Demand Gen and Video are ignored
  const dests = (st.destinationStatuses || []).filter(d => cfg.contexts.includes(d.reportingContext));
  // "Pending initial review" and "Image under review" come back as DISAPPROVED with resolution pending_processing: that's pending
  const issues = (st.itemLevelIssues || [])
    .filter(x => cfg.contexts.includes(x.reportingContext))
    .filter(x => !x.applicableCountries || !x.applicableCountries.length || x.applicableCountries.includes(country))
    .filter(x => x.severity !== 'NOT_IMPACTED')
    // Google's own retries ("No action needed...") are pending too
    .map(x => (x.resolution === 'pending_processing' || /^no action needed/i.test(x.detail || '')) ? { ...x, severity: 'PENDING' } : x)
    .map(x => ({ code: x.code, severity: x.severity, attribute: x.attribute || '', description: x.description || x.code, detail: x.detail || '', documentation: x.documentation || '' }));
  const inC = k => dests.some(d => (d[k] || []).includes(country));
  const waiting = issues.some(x => x.severity === 'PENDING');
  let state;
  if (issues.some(x => x.severity === 'DISAPPROVED') || (inC('disapprovedCountries') && !inC('approvedCountries') && !inC('pendingCountries') && !waiting)) state = 'disapproved';
  else if ((inC('pendingCountries') || waiting) && !inC('approvedCountries')) state = 'pending';
  else if (issues.some(x => x.severity === 'DEMOTED')) state = 'limited';
  else if (inC('approvedCountries')) state = 'approved';
  else state = 'pending';
  // one product can have several variants (offers); the worst state wins
  const real = issues.filter(x => x.severity !== 'PENDING');
  const rank = { disapproved: 3, limited: 2, pending: 1, approved: 0 };
  const dedup = a => { const seen = new Set(); return a.filter(x => { const k = x.code + '|' + x.attribute; if (seen.has(k)) return false; seen.add(k); return true; }); };
  const prev = byProduct[pid];
  if (!prev) byProduct[pid] = { product_id: pid, state, issues: dedup(real), title: (g.productAttributes && g.productAttributes.title) || '' };
  else { if (rank[state] > rank[prev.state]) prev.state = state; prev.issues = dedup(prev.issues.concat(real)); }
}
const out = Object.values(byProduct).map(p => ({ json: p }));
const meta = { total_offers: products.length, unmatched };
if (!out.length) return [{ json: { product_id: null, meta } }];
out[0].json.meta = meta;
return out;

// Google's verdict for every product, and which ones need a card: a disapproved product gets one,
// and a product that had a disapproval card and is fine now gets that card closed.
const old = Object.fromEntries($('Get all status').all().filter(i => i.json.product_id).map(i => [String(i.json.product_id), i.json]));
const now = new Date().toISOString();
return $('One row per product').all().map(i => i.json).filter(p => p.product_id).map(p => {
  const o = old[p.product_id] || {};
  const card = p.state === 'disapproved' ? 'post' : (o.google_state === 'disapproved' && o.slack_ts ? 'resolve' : null);
  return { json: { product_id: p.product_id, google_state: p.state, google_issues: JSON.stringify(p.issues), read_at: now,
    card, title: p.title, issues: p.issues, slack_channel: o.slack_channel || '', slack_ts: o.slack_ts || '' } };
});

// A product Google disapproved gets a review card (the same card the pre-check uses). When Google approves it again, the card is marked fixed.
const cfg = $('Read-back settings').first().json;
if (!cfg.review_channel) return [];
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = DateTime.now().setZone(cfg.timezone).toFormat('h:mm a, d LLL');
const EDITABLE = ['gtin', 'mpn', 'brand', 'title'];
const out = [];
for (const r of $('Decide the cards').all().map(i => i.json)) {
  if (!r.card) continue;
  const title = r.title || 'Product ' + r.product_id;
  const admin = 'https://admin.shopify.com/store/' + cfg.admin_handle + '/products/' + r.product_id;
  const mc = 'https://merchants.google.com/mc/items?a=' + cfg.merchant_id;
  const blocks = [];
  if (r.card === 'resolve') {
    const approved = r.google_state === 'approved' || r.google_state === 'limited';
    blocks.push({ type: 'header', text: { type: 'plain_text', text: approved ? 'Fixed: approved by Google' : 'No action needed' } });
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*' + esc(title) + '*\n' + (approved ? 'Merchant Center no longer disapproves it.' : 'Google is processing it again by itself. The read-back reports it if Google still rejects it afterwards.') } });
    blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Shopify admin' }, url: admin, action_id: 'link_admin' } ] });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: ':white_check_mark: Read back at ' + when } ] });
  } else {
    const issues = r.issues.filter(x => x.severity === 'DISAPPROVED').concat(r.issues.filter(x => x.severity !== 'DISAPPROVED')).slice(0, 8);
    const lines = issues.map(x => '• *' + esc(x.description) + '*' + (x.attribute ? ' (' + esc(x.attribute) + ')' : '') + (x.detail ? '\n      ' + esc(x.detail).slice(0, 200) : '') + (x.documentation ? ' <' + x.documentation + '|How to fix>' : ''));
    blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Disapproved by Google' } });
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*' + esc(title) + '*\n' + (lines.join('\n') || 'Disapproved, with no issue detail from Google.')).slice(0, 2900) } });
    const buttons = [];
    if (issues.some(x => EDITABLE.includes(x.attribute))) buttons.push({ type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Edit' }, action_id: 'google_edit', value: String(r.product_id) });
    buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Recheck' }, action_id: 'google_recheck', value: String(r.product_id) });
    buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Shopify admin' }, url: admin, action_id: 'link_admin' });
    buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Merchant Center' }, url: mc, action_id: 'link_merchant_center' });
    blocks.push({ type: 'actions', elements: buttons });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Passed the pre-check but Google disapproved it. Read back at ' + when } ] });
  }
  out.push({ json: { product_id: String(r.product_id), channel: r.slack_channel || cfg.review_channel, ts: r.slack_ts || '',
    text: (r.card === 'resolve' ? 'Google read-back: ' : 'Disapproved by Google: ') + title, blocks } });
}
return out;

// Approved, limited, disapproved and pending counts, and the most common issues, for the log channel.
const cfg = $('Read-back settings').first().json;
if (!cfg.log_channel) return [];
const ps = $('One row per product').all().map(i => i.json).filter(p => p.product_id);
const meta = $('One row per product').first().json.meta || {};
const n = st => ps.filter(p => p.state === st).length;
const counts = {};
ps.forEach(p => p.issues.forEach(x => { const k = x.description + (x.severity === 'DISAPPROVED' ? ' (disapproved)' : ''); counts[k] = (counts[k] || 0) + 1; }));
const top = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([k, c]) => `    ${c} × ${k}`);
const text = [
  `${ps.length} products in Merchant Center (${meta.total_offers || 0} offers).`,
  `• ${n('approved')} approved`, `• ${n('limited')} limited`, `• ${n('disapproved')} disapproved` + (n('disapproved') ? ' (cards in review)' : ''), `• ${n('pending')} under review`,
  top.length ? 'Top issues:\n' + top.join('\n') : 'No issues.',
  meta.unmatched ? `_${meta.unmatched} offers didn't match a Shopify product id. Check offer_id_pattern._` : ''
].filter(Boolean).join('\n');
return [{ json: { channel: cfg.log_channel, text } }];
